            long long cnt = dp[st];
            if (!cnt) continue;
            int eqPL = st & 1, eqPR = (st >> 1) & 1;
            int eqQL = (st >> 2) & 1, eqQR = (st >> 3) & 1;
            for (int pb = 0; pb <= 1; ++pb) {
