                    int cur = sb ^ pb ^ qb;
                    if (cur == 1) { no[ns] += cnt; hasOne = true; }
                    else nz[ns] += cnt;
                }
            }
        }
        dp = hasOne ? no : nz;
    }
    long long ans = 0;
    for (long long v : dp) ans += v;
